12	import { buildFlagContext } from "./feature-flag-service";
13	import type { RenderedEmail } from "@/server/services/email-service";
14	import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
15	import type { User } from "@/types/member";
16	import type { DigestBundle, DigestEntry } from "@/types/notification";
17	
18	/** A digest with fewer entries than this is not worth an email. */
19	const MIN_ENTRIES = 1;
20	
21	/**
22	 * Collects one recipient's unread notifications inside the window. Returns
23	 * `null` — rather than an empty bundle — when the org's plan does not include
24	 * the digest, or when there is nothing to say: the caller treats `null` as
25	 * "send nothing", so a quiet day produces no mail at all.
26	 */
27	export async function buildDigest(
28	  orgId: OrgId,
29	  recipientId: UserId,
30	  windowStart: IsoTimestamp,
31	  windowEnd: IsoTimestamp,
32	): Promise<DigestBundle | null> {
33	  const org = await orgRepo.findOrgById(orgId);
34	  if (!org) return null;
35	
36	  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;
37	
38	  const unread = await notificationRepo.listUnreadSince(
39	    orgId,
40	    recipientId,
41	    windowStart,
42	  );
43	
44	  const entries: DigestEntry[] = unread
45	    .filter((notification) => notification.createdAt <= windowEnd)
46	    .map((notification) => ({
47	      notificationId: notification.id,
48	      kind: notification.kind,
49	      title: notification.title,
50	      href: notification.href,
51	      occurredAt: notification.createdAt,
52	    }))
53	    .slice(0, DIGEST_MAX_ENTRIES);
54	
55	  if (entries.length < MIN_ENTRIES) return null;
56	
57	  return { orgId, recipientId, entries, windowStart, windowEnd };
58	}
59	
60	/**
61	 * Who gets a digest: everyone who set at least one notification kind to
62	 * `digestOnly`. Opting into the digest is what suppresses the immediate
63	 * emails, so the two lists are two views of the same preference.
64	 */
65	export async function listDigestRecipients(
66	  orgId: OrgId,
67	): Promise<readonly UserId[]> {
68	  return preferenceRepo.listDigestSubscribers(orgId);
69	}
70	
71	/** Renders one bundle through the shared email pipeline. */
72	export async function renderDigest(
73	  bundle: DigestBundle,
74	  recipient: User,
75	): Promise<RenderedEmail> {
76	  return renderEmail("digest", {
77	    orgId: bundle.orgId,
78	    recipientName: recipient.name,
79	    entryCount: bundle.entries.length,
80	    windowStart: bundle.windowStart,
81	    windowEnd: bundle.windowEnd,
82	    headline: bundle.entries[0]?.title ?? "",
83	  });
84	}
 1	/**
 2	 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
 3	 *
 4	 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
 5	 */
 6	import { isEnabled } from "@/lib/feature-flags";
 7	import { createLogger } from "@/lib/logger";
 8	import * as notificationRepo from "@/server/repositories/notification-repository";
 9	import * as orgRepo from "@/server/repositories/organization-repository";
10	import * as usageRepo from "@/server/repositories/usage-repository";
11	import * as userRepo from "@/server/repositories/user-repository";
12	import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
13	import { sendEmail } from "@/server/services/email-service";
14	import { buildFlagContext } from "@/server/services/feature-flag-service";
15	import { toIsoTimestamp } from "@/types/common";
16	import { runJob } from "./types";
17	import type { JobResult } from "@/server/jobs/types";
18	import type { Organization } from "@/types/organization";
19	
20	const ORG_BATCH = 50;
21	const MS_PER_DAY = 24 * 60 * 60 * 1000;
22	
23	const logger = createLogger("digest-email-job");
24	
25	/**
26	 * One pass per scheduler tick. Each org is only processed during the UTC hour
27	 * it configured, so a tick that runs every few minutes still sends exactly one
28	 * digest per day per recipient.
29	 */
30	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
31	  return runJob("digest-email", async (result) => {
32	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
33	
34	    for (const orgId of orgIds) {
35	      const org = await orgRepo.findOrgById(orgId);
36	      if (!org || !shouldRunForOrg(org, now)) continue;
37	
38	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
39	
40	      const windowEnd = toIsoTimestamp(now);
41	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
42	
43	      for (const recipientId of await listDigestRecipients(orgId)) {
44	        try {
45	          const bundle = await buildDigest(
46	            orgId,
47	            recipientId,
48	            windowStart,
49	            windowEnd,
50	          );
51	          if (!bundle) continue;
52	
53	          const recipient = await userRepo.findUserById(recipientId);
54	          if (!recipient) continue;
55	
56	          const rendered = await renderDigest(bundle, recipient);
57	          await sendEmail({ to: recipient.email, ...rendered });
58	
59	          // Once digested, these notifications are no longer "unread" — this
60	          // is what keeps a later run inside the same window from sending
61	          // the same digest twice.
62	          for (const entry of bundle.entries) {
63	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
64	          }
65	
66	          result.processed += 1;
67	        } catch (error) {
68	          result.failed += 1;
69	          logger.error("digest failed", {
70	            orgId,
71	            recipientId,
72	            reason: error instanceof Error ? error.message : String(error),
73	          });
74	        }
75	      }
76	    }
77	  });
78	}
79	
80	/**
81	 * True during the org's configured digest hour. Exported because the schedule
82	 * decision is worth testing on its own, without a database.
83	 */
84	export function shouldRunForOrg(org: Organization, now: Date): boolean {
85	  if (org.archivedAt !== null) return false;
86	  return now.getUTCHours() === org.settings.digestHourUtc;
87	}

