 57	  orgId: OrgId,
 58	  recipientId: UserId,
 59	): PermissionResource {
 60	  return { kind: "notification", orgId, recipientId };
 61	}
 62	
 63	export function webhookResource(
 64	  orgId: OrgId,
 65	  webhookId: WebhookId | null,
 66	): PermissionResource {
 67	  return { kind: "webhook", orgId, webhookId };
 68	}
 69	
 70	export function memberResource(member: Member): PermissionResource {
 71	  return {
 72	    kind: "member",
 73	    orgId: member.orgId,
 74	    memberId: member.id,
 75	    targetUserId: member.userId,
 76	    targetRole: member.role,
 77	  };
 78	}
 79	
 80	export function projectResource(project: Project): PermissionResource {
 81	  return {
 82	    kind: "project",
 83	    orgId: project.orgId,
 84	    projectId: project.id,
 85	    visibility: project.visibility,
 86	    leadId: project.leadId,
 87	  };
 88	}
 89	
 90	export function issueResource(issue: Issue): PermissionResource {
 91	  return {
 92	    kind: "issue",
 93	    orgId: issue.orgId,
 94	    projectId: issue.projectId,
 95	    issueId: issue.id,
 96	    authorId: issue.authorId,
 97	    assigneeId: issue.assigneeId,
 98	  };
 99	}
100	
101	export function commentResource(comment: Comment): PermissionResource {
102	  return {
103	    kind: "comment",
104	    orgId: comment.orgId,
105	    commentId: comment.id,
106	    authorId: comment.authorId,
107	  };
108	}
109	
110	/** The three fields the bus stamps on every payload. */
111	export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
112	  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
113	}
114	
115	/** Same envelope, taken from an `Actor` rather than assembled by hand. */
116	export function actorEnvelope(actor: Actor): EventEnvelope {
117	  return envelope(actor.orgId, actor.userId);
118	}
119	
120	/** Names the fields an update actually changed, for `issue.updated`. */
121	export function changedFields<T extends object>(
122	  before: T,
123	  after: T,
124	): readonly string[] {
125	  return Object.keys(after).filter(
126	    (key) =>
127	      JSON.stringify(before[key as keyof T]) !==
128	      JSON.stringify(after[key as keyof T]),
129	  );
130	}

