  1	import type {
  2	  CommentId,
  3	  IssueId,
  4	  MemberId,
  5	  OrgId,
  6	  ProjectId,
  7	  UserId,
  8	  IsoTimestamp,
  9	} from "./common";
 10	import type { IssueStatus, IssuePriority } from "./issue";
 11	import type { Role } from "./member";
 12	import type { PlanId, LimitedResource } from "./billing";
 13	import type { FeatureFlagKey } from "./feature-flag";
 14	
 15	/** Fields present on every event payload; the bus stamps them on `emit`. */
 16	export interface EventEnvelope {
 17	  readonly orgId: OrgId;
 18	  readonly actorId: UserId | null;
 19	  readonly occurredAt: IsoTimestamp;
 20	}
 21	
 22	/**
 23	 * The complete catalogue of domain events. `emit()` and `subscribe()` in
 24	 * `src/lib/event-bus.ts` are keyed on this map, so adding an event here is the
 25	 * only way to introduce one — services, jobs and the webhook dispatcher all
 26	 * derive their handler signatures from it.
 27	 */
 28	export interface TaskflowEventMap {
 29	  "project.created": EventEnvelope & {
 30	    projectId: ProjectId;
 31	    name: string;
 32	    slug: string;
 33	  };
 34	  "project.archived": EventEnvelope & {
 35	    projectId: ProjectId;
 36	    issuesArchived: number;
 37	  };
 38	  "project.restored": EventEnvelope & { projectId: ProjectId };
 39	  "issue.created": EventEnvelope & {
 40	    issueId: IssueId;
 41	    projectId: ProjectId;
 42	    title: string;
 43	    assigneeId: UserId | null;
 44	    priority: IssuePriority;
 45	  };
 46	  "issue.updated": EventEnvelope & {
 47	    issueId: IssueId;
 48	    projectId: ProjectId;
 49	    changedFields: readonly string[];
 50	  };
 51	  "issue.status_changed": EventEnvelope & {
 52	    issueId: IssueId;
 53	    projectId: ProjectId;
 54	    from: IssueStatus;
 55	    to: IssueStatus;
 56	  };
 57	  "issue.assigned": EventEnvelope & {
 58	    issueId: IssueId;
 59	    projectId: ProjectId;
 60	    previousAssigneeId: UserId | null;
 61	    assigneeId: UserId;
 62	  };
 63	  "issue.archived": EventEnvelope & { issueId: IssueId; projectId: ProjectId };
 64	  "issue.overdue": EventEnvelope & {
 65	    issueId: IssueId;
 66	    projectId: ProjectId;
 67	    dueAt: IsoTimestamp;
 68	    assigneeId: UserId | null;
 69	  };
 70	  "comment.created": EventEnvelope & {
 71	    commentId: CommentId;
 72	    issueId: IssueId;
 73	    mentionedUserIds: readonly UserId[];
 74	  };
 75	  "comment.deleted": EventEnvelope & { commentId: CommentId; issueId: IssueId };
 76	  "member.invited": EventEnvelope & { email: string; role: Role };
 77	  "member.joined": EventEnvelope & { memberId: MemberId; userId: UserId; role: Role };
 78	  "member.role_changed": EventEnvelope & {
 79	    memberId: MemberId;
 80	    from: Role;
 81	    to: Role;
 82	  };
 83	  "member.removed": EventEnvelope & { memberId: MemberId; userId: UserId };
 84	  "billing.plan_changed": EventEnvelope & { from: PlanId; to: PlanId };
 85	  "billing.limit_exceeded": EventEnvelope & {
 86	    resource: LimitedResource;
 87	    limit: number;
 88	    used: number;
 89	  };
 90	  "flag.toggled": EventEnvelope & { flag: FeatureFlagKey; enabled: boolean };
 91	  "digest.due": EventEnvelope & { recipientId: UserId; windowStart: IsoTimestamp };
