  1	/**
  2	 * Project lifecycle including the project-count quota and the cascade that archives a project's issues.
  3	 *
  4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, uniqueSlug, projectKeyFromName
  5	 */
  6	import { wouldExceedLimit } from "@/config/plan-limits";
  7	import { emit } from "@/lib/event-bus";
  8	import { assertCan } from "@/lib/permissions";
  9	import { projectKeyFromName, uniqueSlug } from "@/lib/slug";
 10	import { assertNotArchived } from "@/lib/soft-delete";
 11	import { assertOrgScope } from "@/lib/tenant";
 12	import * as issueRepo from "@/server/repositories/issue-repository";
 13	import * as orgRepo from "@/server/repositories/organization-repository";
 14	import * as projectRepo from "@/server/repositories/project-repository";
 15	import {
 16	  actorEnvelope,
 17	  orgResource,
 18	  projectResource,
 19	  requireFound,
 20	} from "./_support";
 21	import type {
 22	  ArchiveProjectInput,
 23	  CreateProjectInput,
 24	  ListProjectsInput,
 25	  UpdateProjectInput,
 26	} from "@/schemas/project";
 27	import type { OrgId, Page, ProjectId } from "@/types/common";
 28	import type { Actor } from "@/types/member";
 29	import type { Project, ProjectWithStats } from "@/types/project";
 30	
 31	/**
 32	 * Creates a project once the plan still has room for one. The key is derived
 33	 * from the name when the caller left it blank, so the issue numbering scheme
 34	 * (`TF-12`) is never invented at the call site.
 35	 */
 36	export async function createProject(
 37	  actor: Actor,
 38	  input: CreateProjectInput,
 39	): Promise<Project> {
 40	  assertOrgScope(actor, input.orgId);
 41	  assertCan(actor, "project:create", orgResource(input.orgId));
 42	
 43	  const org = requireFound(
 44	    await orgRepo.findOrgById(input.orgId),
 45	    "Organization",
 46	    input.orgId,
 47	  );
 48	
 49	  const used = await projectRepo.countProjects(input.orgId);
 50	  if (wouldExceedLimit(org.plan, "projects", used)) {
 51	    throw new Error(
 52	      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
 53	    );
 54	  }
 55	
 56	  const slug = await suggestProjectSlug(input.orgId, input.name);
 57	
 58	  const project = await projectRepo.insertProject({
 59	    ...input,
 60	    slug,
 61	    key: input.key || projectKeyFromName(input.name),
 62	  });
 63	
 64	  await emit("project.created", {
 65	    ...actorEnvelope(actor),
 66	    projectId: project.id,
 67	    name: project.name,
 68	    slug: project.slug,
 69	  });
 70	
 71	  return project;
 72	}
 73	
 74	export async function updateProject(
 75	  actor: Actor,
 76	  input: UpdateProjectInput,
 77	): Promise<Project> {
 78	  assertOrgScope(actor, input.orgId);
 79	
 80	  const project = requireFound(
 81	    await projectRepo.findProjectById(input.orgId, input.projectId),
 82	    "Project",
 83	    input.projectId,
 84	  );
 85	  assertCan(actor, "project:update", projectResource(project));
 86	  assertNotArchived("Project", project.id, project);
 87	
 88	  return projectRepo.updateProject(input);
 89	}
 90	
 91	/**
 92	 * Archiving a project cascades to its issues by default — leaving live issues
 93	 * behind an archived project is the drift this flag exists to prevent.
 94	 */
 95	export async function archiveProject(
 96	  actor: Actor,
 97	  input: ArchiveProjectInput,
 98	): Promise<Project> {
 99	  assertOrgScope(actor, input.orgId);
100	
101	  const project = requireFound(
102	    await projectRepo.findProjectById(input.orgId, input.projectId),
103	    "Project",
104	    input.projectId,
105	  );
106	  assertCan(actor, "project:archive", projectResource(project));
107	  assertNotArchived("Project", project.id, project);
108	
109	  const issuesArchived = input.archiveIssues
110	    ? await issueRepo.archiveIssuesForProject(input.orgId, input.projectId)
111	    : 0;
112	
113	  const archived = await projectRepo.archiveProject(
114	    input.orgId,
115	    input.projectId,
116	  );
117	
118	  await emit("project.archived", {
119	    ...actorEnvelope(actor),
120	    projectId: archived.id,
121	    issuesArchived,
122	  });
123	
124	  return archived;
125	}
126	
127	/** Restore does not un-archive the issues: they are restored individually. */
128	export async function restoreProject(
129	  actor: Actor,
130	  orgId: OrgId,
131	  projectId: ProjectId,
132	): Promise<Project> {
133	  assertOrgScope(actor, orgId);
134	
135	  const project = requireFound(
136	    await projectRepo.findProjectById(orgId, projectId),
137	    "Project",
138	    projectId,
139	  );
140	  assertCan(actor, "project:archive", projectResource(project));
141	
142	  const restored = await projectRepo.restoreProject(orgId, projectId);
143	
144	  await emit("project.restored", {
145	    ...actorEnvelope(actor),
146	    projectId: restored.id,
147	  });
148	
149	  return restored;
150	}

