  1	/**
  2	 * In-memory SQLite fixture: migrate, seed a tenant pair, reset between tests.
  3	 *
  4	 * Repository and service suites call `setupTestDb()` once, `resetTestDb()` in
  5	 * `beforeEach` and `seedTwoTenants()` when they need two organizations to
  6	 * prove a query is org-scoped. The database is `:memory:`, so nothing here
  7	 * touches the developer's `data/taskflow.db`.
  8	 */
  9	// Aliased on import: the contract calls it `useInMemoryDb`, which the
 10	// react-hooks lint rule would otherwise mistake for a React hook here.
 11	import { getDb, useInMemoryDb as attachInMemoryDb } from "@/server/db";
 12	import { runMigrations } from "@/server/db/migrate";
 13	import { organizations } from "@/server/db/schema/organizations";
 14	import { users } from "@/server/db/schema/users";
 15	import type { Organization } from "@/types/organization";
 16	import { makeOrganization, ORG_A, ORG_B } from "./factories";
 17	
 18	let migrated = false;
 19	
 20	/** Points the singleton client at an in-memory database and migrates it. */
 21	export async function setupTestDb(): Promise<void> {
 22	  attachInMemoryDb();
 23	  await runMigrations(":memory:");
 24	  migrated = true;
 25	}
 26	
 27	/** Truncates every table, keeping the schema — cheaper than re-migrating. */
 28	export async function resetTestDb(): Promise<void> {
 29	  if (!migrated) await setupTestDb();
 30	
 31	  const db = getDb();
 32	  const tables = db.$client
 33	    .prepare(
 34	      "SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '__drizzle%'",
 35	    )
 36	    .all() as readonly { name: string }[];
 37	
 38	  db.$client.pragma("foreign_keys = OFF");
 39	  for (const table of tables) {
 40	    db.$client.prepare(`DELETE FROM "${table.name}"`).run();
 41	  }
 42	  db.$client.pragma("foreign_keys = ON");
 43	}
 44	
 45	/**
 46	 * Inserts two organizations owned by two different users. Every "does this
 47	 * query filter by orgId?" test seeds through here so the negative case is a
 48	 * real row in a real other tenant, not an absence.
 49	 */
 50	export async function seedTwoTenants(): Promise<{
 51	  orgA: Organization;
 52	  orgB: Organization;
 53	}> {
 54	  const db = getDb();
 55	
 56	  const orgA = makeOrganization({ id: ORG_A, name: "Acme", slug: "acme" });
 57	  const orgB = makeOrganization({
 58	    id: ORG_B,
 59	    name: "Globex",
 60	    slug: "globex",
 61	    ownerId: orgA.ownerId,
 62	  });
 63	
 64	  await db
 65	    .insert(users)
 66	    .values({
 67	      id: orgA.ownerId,
 68	      email: "owner@example.com",
 69	      name: "Test Owner",
 70	      passwordHash: "scrypt:00:00",
 71	      timezone: "UTC",
 72	      createdAt: orgA.createdAt,
 73	      updatedAt: orgA.updatedAt,
 74	    })
 75	    .onConflictDoNothing();
 76	
 77	  for (const org of [orgA, orgB]) {
 78	    await db.insert(organizations).values({
 79	      id: org.id,
 80	      name: org.name,
 81	      slug: org.slug,
 82	      ownerId: org.ownerId,
 83	      plan: org.plan,
 84	      logoUrl: org.logoUrl,
 85	      trialEndsAt: org.trialEndsAt,
 86	      // `OrganizationSettings` is flattened across columns on this table.
 87	      defaultIssueStatus: org.settings.defaultIssueStatus,
 88	      allowPublicProjects: org.settings.allowPublicProjects,
 89	      requireTwoFactor: org.settings.requireTwoFactor,
 90	      digestHourUtc: org.settings.digestHourUtc,
 91	      enabledFlagOverrides: JSON.stringify(org.settings.enabledFlagOverrides),
 92	      archivedAt: org.archivedAt,
 93	      createdAt: org.createdAt,
 94	      updatedAt: org.updatedAt,
 95	    });
 96	  }
 97	
 98	  return { orgA, orgB };
 99	}
