  1	/**
  2	 * Deterministic factories for actors, orgs, projects, issues and comments
  3	 * used across the suite.
  4	 *
  5	 * Every factory seeds from the same `idFactory`, so a test that does not care
  6	 * about ids gets stable ones, and a test that does can override them. All
  7	 * default rows live in `ORG_A` — cross-tenant tests pass `orgId: ORG_B`.
  8	 */
  9	import { idFactory } from "@/lib/id";
 10	import type { LimitCheck } from "@/types/billing";
 11	import type { Comment } from "@/types/comment";
 12	import type {
 13	  CommentId,
 14	  IsoTimestamp,
 15	  IssueId,
 16	  MemberId,
 17	  OrgId,
 18	  ProjectId,
 19	  UserId,
 20	} from "@/types/common";
 21	import type { Issue } from "@/types/issue";
 22	import type { Actor, MemberWithUser, User } from "@/types/member";
 23	import type { Organization } from "@/types/organization";
 24	import type { Project } from "@/types/project";
 25	
 26	const nextId = idFactory(42);
 27	
 28	/** The default tenant every factory row belongs to. */
 29	export const ORG_A = "01HZZZAAAAAAAAAAAAAAAAAAAA" as OrgId;
 30	/** A second tenant, for cross-tenant assertions. */
 31	export const ORG_B = "01HZZZBBBBBBBBBBBBBBBBBBBB" as OrgId;
 32	
 33	export const ALICE = "01HZZZAAAAAAAAAAAAAAAAAAA1" as UserId;
