107	
108	    await insertNotificationAt(tenant, new Date(now.getTime() - 12 * 3_600_000), "Recent update");
109	    await insertNotificationAt(tenant, new Date(now.getTime() - 30 * 3_600_000), "Stale update");
110	
111	    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
112	
113	    await runDigestEmailJob(now);
114	
115	    expect(sendSpy).toHaveBeenCalledTimes(1);
