  3	 */
  4	import { and, eq } from "drizzle-orm";
  5	import { getDb, projectMembers } from "@/server/db";
  6	import { toIsoTimestamp } from "@/types/common";
  7	import { brandId } from "./_mappers";
  8	import { orgPredicate } from "./base-repository";
  9	import type { OrgId, ProjectId, UserId } from "@/types/common";
 10	
 11	export async function listProjectMemberIds(
 12	  orgId: OrgId,
 13	  projectId: ProjectId,
 14	): Promise<readonly UserId[]> {
 15	  const rows = getDb()
 16	    .select({ userId: projectMembers.userId })
 17	    .from(projectMembers)
 18	    .where(
 19	      and(
 20	        orgPredicate(projectMembers.orgId, orgId),
 21	        eq(projectMembers.projectId, projectId),
 22	      ),
 23	    )
 24	    .all();
 25	  return rows.map((row) => brandId<UserId>(row.userId));
 26	}
 27	
 28	/** Idempotent: re-adding an existing member is a no-op, not a conflict. */
 29	export async function addProjectMember(
 30	  orgId: OrgId,
 31	  projectId: ProjectId,
 32	  userId: UserId,
 33	): Promise<void> {
 34	  if (await isProjectMember(orgId, projectId, userId)) return;
 35	
 36	  getDb()
 37	    .insert(projectMembers)
 38	    .values({
 39	      orgId,
 40	      projectId,
 41	      userId,
 42	      addedAt: toIsoTimestamp(new Date()),
 43	    })
 44	    .run();
 45	}
 46	
 47	export async function removeProjectMember(
 48	  orgId: OrgId,
 49	  projectId: ProjectId,
 50	  userId: UserId,
 51	): Promise<void> {
 52	  getDb()
 53	    .delete(projectMembers)
 54	    .where(
 55	      and(
 56	        orgPredicate(projectMembers.orgId, orgId),
 57	        eq(projectMembers.projectId, projectId),
 58	        eq(projectMembers.userId, userId),
 59	      ),
 60	    )
 61	    .run();
 62	}
 63	
 64	export async function isProjectMember(
 65	  orgId: OrgId,
 66	  projectId: ProjectId,
 67	  userId: UserId,
 68	): Promise<boolean> {
 69	  const row = getDb()
 70	    .select({ userId: projectMembers.userId })
 71	    .from(projectMembers)
 72	    .where(
 73	      and(
 74	        orgPredicate(projectMembers.orgId, orgId),
 75	        eq(projectMembers.projectId, projectId),
 76	        eq(projectMembers.userId, userId),
 77	      ),
 78	    )
 79	    .get();
 80	  return row !== undefined;
 81	}
  1	/**
  2	 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
  3	 *
  4	 * Must call (do not reimplement): shouldFilterArchived
  5	 */
  6	import { eq, isNull } from "drizzle-orm";
  7	import { shouldFilterArchived } from "@/lib/soft-delete";
  8	import type { ArchiveScope, OrgId } from "@/types/common";
  9	import type { SQL } from "drizzle-orm";
 10	import type { SQLiteColumn } from "drizzle-orm/sqlite-core";
 11	
 12	const CURSOR_SEPARATOR = "|";
 13	
 14	/**
 15	 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
 16	 * sort value alongside the id is what lets `listX` resume from a stable point
 17	 * even when two rows share a timestamp.
 18	 */
 19	export function encodeCursor(id: string, sortValue: string): string {
 20	  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
 21	    "base64url",
 22	  );
 23	}
 24	
 25	export function decodeCursor(
 26	  cursor: string,
 27	): { id: string; sortValue: string } | null {
 28	  let decoded: string;
 29	  try {
 30	    decoded = Buffer.from(cursor, "base64url").toString("utf8");
 31	  } catch {
 32	    return null;
 33	  }
 34	
 35	  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
 36	  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;
 37	
 38	  return {
 39	    sortValue: decoded.slice(0, separatorAt),
 40	    id: decoded.slice(separatorAt + 1),
 41	  };
 42	}
 43	
 44	/**
 45	 * The tenant predicate. Every repository read and write composes this — a
 46	 * query that does not mention `org_id` is a cross-tenant leak waiting to
 47	 * happen, so this is the only sanctioned way to express it.
 48	 */
 49	export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
 50	  return eq(column, orgId);
 51	}
 52	
 53	/**
 54	 * The soft-delete predicate, or `undefined` when the caller explicitly asked
 55	 * for archived rows. The `includeArchived` decision itself lives in
 56	 * `shouldFilterArchived()` so it cannot drift per repository.
 57	 */
 58	export function livePredicate(
 59	  column: SQLiteColumn,
 60	  scope: ArchiveScope,
 61	): SQL | undefined {
 62	  return shouldFilterArchived(scope) ? isNull(column) : undefined;
 63	}

