    expect(await listMutedProjectIds(tenant.actors.admin, tenant.org.id)).toEqual([]);
    await unmuteProject(tenant.actors.viewer, tenant.org.id, tenant.project.id);
    await unmuteProject(tenant.actors.viewer, tenant.org.id, tenant.project.id);
    expect(await listMutedProjectIds(tenant.actors.viewer, tenant.org.id)).toEqual([]);
  });

  it("notify rules", async () => {
    await muteProject(tenant.actors.admin, tenant.org.id, tenant.project.id);
    const p = { title: "t", body: "b", href: "/x", actorId: null, projectId: tenant.project.id };
    expect(await notify(tenant.org.id, "comment_created", [tenant.userIds.admin, tenant.userIds.viewer], p)).toHaveLength(1);
    const a = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.admin, tenant.userIds.viewer], p);
    expect(a.map((r) => [r.recipientId === tenant.userIds.admin, r.channels, r.projectId])).toEqual([
      [true, ["in_app"], tenant.project.id],
      [false, ["in_app", "email"], tenant.project.id],
    ]);
    const nop = await notify(tenant.org.id, "comment_created", [tenant.userIds.admin], { ...p, projectId: undefined });
    expect(nop).toHaveLength(1);
    expect(nop[0]?.projectId).toBeNull();

    // fan-out
    const issue = await issueService.createIssue(tenant.actors.member, issueInput(tenant.org.id, tenant.project.id, { title: "x" }));
    await emit("comment.created", {
      orgId: tenant.org.id, actorId: tenant.userIds.member, occurredAt: issue.createdAt,
      commentId: "c1" as CommentId, issueId: issue.id, mentionedUserIds: [tenant.userIds.admin],
    });
    const page = await listNotifications(tenant.actors.admin, { orgId: tenant.org.id, recipientId: tenant.userIds.admin, unreadOnly: false, kind: ["comment_mention"], limit: 25, cursor: null });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]?.channels).toEqual(["in_app"]);
    expect(page.items[0]?.projectId).toBe(tenant.project.id);
    await unmuteProject(tenant.actors.admin, tenant.org.id, tenant.project.id);
  });

  it("digest", async () => {
    const t = await createTenant("mute-digest", "growth");
    await orgRepo.updateOrg(t.org.id, { orgId: t.org.id, settings: { digestHourUtc: 9 } });
    await usageRepo.recomputeUsage(t.org.id);
    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.member, kind: "comment_created", inApp: false, email: false, digestOnly: true });
    const now = new Date(Date.UTC(2026, 5, 1, 9));
    vi.useFakeTimers(); vi.setSystemTime(new Date(now.getTime() - 3600_000));
    await notificationRepo.insertNotification(t.org.id, { orgId: t.org.id, recipientId: t.userIds.member, kind: "comment_created", title: "muted one", body: "", href: "/", actorId: null, channels: ["email"], projectId: t.project.id });
    vi.useRealTimers();
    await muteProject(t.actors.member, t.org.id, t.project.id);
    const spy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
    await runDigestEmailJob(now);
    expect(spy).not.toHaveBeenCalled();
    await unmuteProject(t.actors.member, t.org.id, t.project.id);
    await runDigestEmailJob(now);
    expect(spy).toHaveBeenCalledTimes(1);
  });
});
